text:
{
  "headline": "FDA's records trace our supply to plants with OAI classifications 797 and 1530 days before the shortage posting",
  "headline_cites": ["D4", "D5"],
  "sentences": [
    {
      "text": "FDA first posted the remifentanil hydrochloride shortage on 2022-06-28 and it has remained current for 52 months as of 2026-10-21.",
      "cites": ["E24", "D7"]
    },
    {
      "text": "The shortage lists Fresenius Kabi USA, LLC, Hikma Pharmaceuticals USA, Inc., and Mylan Institutional as affected manufacturers.",
      "cites": ["E21", "E22", "E23"]
    },
    {
      "text": "Our inventory at both Corvale General and Corvale Lakeside carries NDC 00143939210 labeled by Hikma Pharmaceuticals USA Inc.",
      "cites": ["E1", "E2"]
    },
    {
      "text": "That NDC maps to label set 9d289052 which names Hospira, Inc. and Navinta LLC as registered manufacturing plants.",
      "cites": ["E14", "E20"]
    },
    {
      "text": "FDA's OAI classification letter to Hospira, Inc. is dated 2020-04-22, 797 days before the shortage posting.",
      "cites": ["D4"]
    },
    {
      "text": "FDA's OAI classification letter to Navinta LLC is dated 2018-04-20, 1530 days before the shortage posting.",
      "cites": ["D5"]
    },
    {
      "text": "The rule-based transfer option moves 16 units from Corvale General (17 days on hand) to Corvale Lakeside (6.8 days on hand) so both sites reach at least two weeks of supply.",
      "cites": ["D1", "D2", "D6"]
    }
  ]
}
